SELECT 'tracker_tags'::text AS view_name, 'tags'::text AS domain, 'Every tag ever written to a tracker row (current and superseded), joined to the tracker row, product and taxonomy line. Filter is_current for what stands now.'::text AS description, 'one row per tag_id'::text AS grain, (SELECT min(tagged_at::date) FROM public.ad_tags)::date AS first_day, (SELECT max(tagged_at::date) FROM public.ad_tags)::date AS last_day, (SELECT NULLIF(c.reltuples, -1)::bigint FROM pg_class c WHERE c.oid = to_regclass('public.ad_tags')) AS row_estimate
UNION ALL
SELECT 'tracker_hooks'::text AS view_name, 'tags'::text AS domain, 'The hook of each tracker row: the first spoken line and the first on-screen text, joined to the tracker row and product.'::text AS description, 'one row per tracker_row_id'::text AS grain, (SELECT min(extracted_at::date) FROM public.ad_hooks)::date AS first_day, (SELECT max(extracted_at::date) FROM public.ad_hooks)::date AS last_day, (SELECT NULLIF(c.reltuples, -1)::bigint FROM pg_class c WHERE c.oid = to_regclass('public.ad_hooks')) AS row_estimate
UNION ALL
SELECT 'priorities_snapshots'::text AS view_name, 'priorities'::text AS domain, 'One row per weekly creative priorities snapshot: when it was built, the data it used and how many rows it holds.'::text AS description, 'one row per week_start (the Sunday, Pacific)'::text AS grain, (SELECT min(week_start) FROM public.creative_priorities_snapshots)::date AS first_day, (SELECT max(week_start) FROM public.creative_priorities_snapshots)::date AS last_day, (SELECT NULLIF(c.reltuples, -1)::bigint FROM pg_class c WHERE c.oid = to_regclass('public.creative_priorities_snapshots')) AS row_estimate
UNION ALL
SELECT 'priorities_thresholds'::text AS view_name, 'priorities'::text AS domain, 'Every threshold and weight the week was scored with (HIT_SPEND, TOP_SPEND, JUDGED_SPEND, MIN_LINE_SPEND, the score weights ...), one row per (week, name).'::text AS description, 'one row per (week_start, name)'::text AS grain, (SELECT min(week_start) FROM public.creative_priorities_snapshots)::date AS first_day, (SELECT max(week_start) FROM public.creative_priorities_snapshots)::date AS last_day, (SELECT NULLIF(c.reltuples, -1)::bigint FROM pg_class c WHERE c.oid = to_regclass('public.creative_priorities_snapshots')) AS row_estimate
UNION ALL
SELECT 'priorities_baselines'::text AS view_name, 'priorities'::text AS domain, 'The product averages each line is compared with (ROAS, CPA, hit rate, spend, funnel counts), one numeric row per (week, product, metric).'::text AS description, 'one row per (week_start, product_slug, metric)'::text AS grain, (SELECT min(week_start) FROM public.creative_priorities_snapshots)::date AS first_day, (SELECT max(week_start) FROM public.creative_priorities_snapshots)::date AS last_day, (SELECT NULLIF(c.reltuples, -1)::bigint FROM pg_class c WHERE c.oid = to_regclass('public.creative_priorities_snapshots')) AS row_estimate
UNION ALL
SELECT 'priorities_concepts'::text AS view_name, 'priorities'::text AS domain, 'Every row of every weekly priorities snapshot, flattened: the line (cluster, ICP, pain point), its action section and status, score, confidence and the numbers behind it (Meta-reported, with Upstack new-customer ROAS beside them).'::text AS description, 'one row per (week_start, row of the snapshot)'::text AS grain, (SELECT min(week_start) FROM public.creative_priorities_snapshots)::date AS first_day, (SELECT max(week_start) FROM public.creative_priorities_snapshots)::date AS last_day, (SELECT NULLIF(c.reltuples, -1)::bigint FROM pg_class c WHERE c.oid = to_regclass('public.creative_priorities_snapshots')) AS row_estimate
UNION ALL
SELECT 'priorities_manual_concepts'::text AS view_name, 'priorities'::text AS domain, 'Concepts typed in by hand on the priorities page (not scored): product, section, line, why now and status.'::text AS description, 'one row per manual_id'::text AS grain, (SELECT min(created_at::date) FROM public.creative_priorities_manual)::date AS first_day, (SELECT max(created_at::date) FROM public.creative_priorities_manual)::date AS last_day, (SELECT NULLIF(c.reltuples, -1)::bigint FROM pg_class c WHERE c.oid = to_regclass('public.creative_priorities_manual')) AS row_estimate
UNION ALL
SELECT 'production_assignments'::text AS view_name, 'production'::text AS domain, 'One concept given to one vendor to make for one week: the line, the brief and creative links, the timestamp of each step and the tracker concepts it became.'::text AS description, 'one row per assignment_id'::text AS grain, (SELECT min(for_week) FROM public.creative_priorities_assignments)::date AS first_day, (SELECT max(for_week) FROM public.creative_priorities_assignments)::date AS last_day, (SELECT NULLIF(c.reltuples, -1)::bigint FROM pg_class c WHERE c.oid = to_regclass('public.creative_priorities_assignments')) AS row_estimate
UNION ALL
SELECT 'production_formats'::text AS view_name, 'production'::text AS domain, 'The creative formats (static, short video, ...) an assignment can carry.'::text AS description, 'one row per format_code'::text AS grain, NULL::date AS first_day, NULL::date AS last_day, (SELECT NULLIF(c.reltuples, -1)::bigint FROM pg_class c WHERE c.oid = to_regclass('public.creative_formats')) AS row_estimate
UNION ALL
SELECT 'competitor_brands'::text AS view_name, 'competitors'::text AS domain, 'The competitor brands tracked in the Meta Ad Library and when each was last read.'::text AS description, 'one row per brand'::text AS grain, NULL::date AS first_day, NULL::date AS last_day, (SELECT NULLIF(c.reltuples, -1)::bigint FROM pg_class c WHERE c.oid = to_regclass('public.competitor_brands')) AS row_estimate
UNION ALL
SELECT 'competitor_ads'::text AS view_name, 'competitors'::text AS domain, 'Weekly snapshot of each competitor ad found in the Meta Ad Library: format, copy, hook, landing page and how long it has been running.'::text AS description, 'one row per (week_start, library_id)'::text AS grain, (SELECT min(week_start) FROM public.competitor_ads)::date AS first_day, (SELECT max(seen_on) FROM public.competitor_ads)::date AS last_day, (SELECT NULLIF(c.reltuples, -1)::bigint FROM pg_class c WHERE c.oid = to_regclass('public.competitor_ads')) AS row_estimate
UNION ALL
SELECT 'competitor_concepts'::text AS view_name, 'competitors'::text AS domain, 'Competitor ads grouped into concepts per week and mapped to our product, line, cluster, ICP and pain point (or flagged as a new angle).'::text AS description, 'one row per (week_start, brand, concept_key)'::text AS grain, (SELECT min(week_start) FROM public.competitor_ads)::date AS first_day, (SELECT max(seen_on) FROM public.competitor_ads)::date AS last_day, (SELECT NULLIF(c.reltuples, -1)::bigint FROM pg_class c WHERE c.oid = to_regclass('public.competitor_ads')) AS row_estimate
UNION ALL
SELECT 'catalog'::text AS view_name, 'pipeline'::text AS domain, 'One row per analytics view: its domain, what it is, its grain, the first and last day it covers where it has days, and a row-count estimate. Start here to find which view answers a question.'::text AS description, 'one row per analytics view (this view itself is listed too)'::text AS grain, NULL::date AS first_day, NULL::date AS last_day, NULL::bigint AS row_estimate
UNION ALL
SELECT 'metric_glossary'::text AS view_name, 'pipeline'::text AS domain, 'The canonical definition of every headline metric (ROAS, CPA, NC ROAS, CPM, frequency, hit rate, payback, ...): formula, the view and columns that hold the inputs, the default basis, the other bases and the traps. The same rows as the ''metrics'' key of docs/schema.json.'::text AS description, 'one row per metric name'::text AS grain, NULL::date AS first_day, NULL::date AS last_day, NULL::bigint AS row_estimate
UNION ALL
SELECT 'klaviyo_daily'::text AS view_name, 'email'::text AS domain, 'Klaviyo email and SMS performance by Pacific day, campaign or flow, message and channel: sends, delivered, opens, clicks, unsubscribes and Klaviyo-attributed orders and revenue.'::text AS description, 'one row per day (Pacific) x source (''campaign'' | ''flow'') x parent_id x message_id x channel (that is the primary key; message_id is '''' where Klaviyo gives none)'::text AS grain, NULL::date AS first_day, NULL::date AS last_day, NULL::bigint AS row_estimate
UNION ALL
SELECT 'klaviyo_campaigns'::text AS view_name, 'email'::text AS domain, 'Dimension: one row per Klaviyo campaign (email and SMS) with its name, status, send time and subject. Names the parent ids of klaviyo_daily.'::text AS description, 'one row per campaign (id is the primary key; Klaviyo campaign id)'::text AS grain, NULL::date AS first_day, NULL::date AS last_day, NULL::bigint AS row_estimate
UNION ALL
SELECT 'klaviyo_flows'::text AS view_name, 'email'::text AS domain, 'Dimension: one row per Klaviyo flow with its name, status and trigger type. Names the parent ids of klaviyo_daily.'::text AS description, 'one row per flow (id is the primary key; Klaviyo flow id)'::text AS grain, NULL::date AS first_day, NULL::date AS last_day, NULL::bigint AS row_estimate
UNION ALL
SELECT 'klaviyo_flow_messages'::text AS view_name, 'email'::text AS domain, 'Dimension: one row per message (email or SMS step) inside a Klaviyo flow, with its name and subject. Names the message_id of klaviyo_daily flow rows.'::text AS description, 'one row per flow message (id is the primary key; Klaviyo flow message id)'::text AS grain, NULL::date AS first_day, NULL::date AS last_day, NULL::bigint AS row_estimate
UNION ALL
SELECT 'klaviyo_message_content'::text AS view_name, 'email'::text AS domain, 'The copy of every Klaviyo message (campaign message or flow message) that had activity in a pulled window, or that sits in a live flow: subject, preview text, full email HTML, readable body text and the message links. Joins to klaviyo_daily on message_id.'::text AS description, 'one row per message (message_id is the primary key; Klaviyo campaign message id or flow message id)'::text AS grain, NULL::date AS first_day, NULL::date AS last_day, NULL::bigint AS row_estimate
UNION ALL
SELECT 'klaviyo_message_performance'::text AS view_name, 'email'::text AS domain, 'One row per Klaviyo message with its copy (subject, preview text, body text) and its totals and rates over everything in klaviyo_daily: the table to read which copy earns.'::text AS description, 'one row per message_id (campaign or flow message with at least one klaviyo_daily row)'::text AS grain, NULL::date AS first_day, NULL::date AS last_day, NULL::bigint AS row_estimate
UNION ALL
SELECT 'landing_pages'::text AS view_name, 'landing_pages'::text AS domain, 'Every landing page (sales page, advertorial, product page, funnel step) that at least one Meta ad sends people to, with when we last read it.'::text AS description, 'one row per normalised page address (id is the primary key; url is unique)'::text AS grain, NULL::date AS first_day, NULL::date AS last_day, NULL::bigint AS row_estimate
UNION ALL
SELECT 'landing_page_versions'::text AS view_name, 'landing_pages'::text AS domain, 'The copy of a landing page as it was on a given read: title, description, ordered text blocks with heading level, buttons, prices, guarantee sentences, review snippets and image alt text.'::text AS description, 'one row per (landing page, content hash): a new row exists only when the copy changed (id is the primary key)'::text AS grain, NULL::date AS first_day, NULL::date AS last_day, NULL::bigint AS row_estimate
UNION ALL
SELECT 'landing_page_ads'::text AS view_name, 'landing_pages'::text AS domain, 'Which Meta ad sends people to which landing page, and how that link was found.'::text AS description, 'one row per (ad, landing page) (ad_id + landing_page_id is the primary key)'::text AS grain, NULL::date AS first_day, NULL::date AS last_day, NULL::bigint AS row_estimate
UNION ALL
SELECT 'landing_page_ad_checks'::text AS view_name, 'landing_pages'::text AS domain, 'Ads that etl/landing_pages.py has already looked at, so an ad with no readable link is not asked about every night.'::text AS description, 'one row per ad (ad_id is the primary key)'::text AS grain, NULL::date AS first_day, NULL::date AS last_day, NULL::bigint AS row_estimate
UNION ALL
SELECT 'landing_page_top_ads'::text AS view_name, 'landing_pages'::text AS domain, 'The ads that drive each landing page, ranked by spend over the last 7 and the last 30 days, with Meta-reported purchases, revenue and ROAS (revenue divided by spend).'::text AS description, 'one row per (landing page, window_days, ad): window_days is 7 or 30; only ads with spend in the window appear'::text AS grain, NULL::date AS first_day, NULL::date AS last_day, NULL::bigint AS row_estimate
UNION ALL
SELECT 'shopify_orders'::text AS view_name, 'orders'::text AS domain, 'Order-level Shopify orders of the last 120 days (rolling), one row per order, with money, status, source, discount codes and ship-to country / region. The place to answer order-level questions (refunds, rebills, gifts, discounts) that the daily roll-ups hide.'::text AS description, 'one row per Shopify order (order_id is the primary key)'::text AS grain, NULL::date AS first_day, NULL::date AS last_day, NULL::bigint AS row_estimate
UNION ALL
SELECT 'shopify_order_lines'::text AS view_name, 'orders'::text AS domain, 'Line items of shopify_orders: one row per product line with SKU, product bucket, quantity, price and discount.'::text AS description, 'one row per order line (order_id, line_no is the primary key; line_no counts from 1 in the order''s own line order)'::text AS grain, NULL::date AS first_day, NULL::date AS last_day, NULL::bigint AS row_estimate
) k(view_name, domain, description, grain, first_day, last_day, row_estimate) ON k.view_name = c.relname
WHERE c.relkind = 'v';

CREATE OR REPLACE VIEW analytics.metric_glossary AS
SELECT g.name::text, g.label::text, g.formula::text, g.source::text, g.default_basis::text, g.other_bases, g.traps, g.domain::text
FROM (VALUES
  ('spend', 'Ad spend', 'sum(spend) over the days. Total spend = Meta spend + Google spend; a ratio''s spend is always the sum over the same days and rows as its numerator.', 'analytics.meta_ad_daily.spend; analytics.google_campaign_daily.spend; analytics.platform_daily.spend', 'Meta (Graph API, both ad accounts) + Google Ads, platform-reported dollars: the ''Total spend'' of the Marketing metrics app (app/trends.py build_catalog(), total_spend).', ARRAY['Meta spend alone (the product bands'' Total column divides by it)', 'Business-wide spend in pacing = Meta + Google + TikTok and other platforms + Amazon ads (app/projection/pacing/catalog.py, biz_total_spend)', 'analytics.platform_daily_history.spend for days before 2026-05-06 (Meta ad level starts 2026-05-06; campaign grain from 2024-12-31 in analytics.meta_campaign_daily_history)']::text[], ARRAY['Spend adds across platforms; purchases and revenue never do.', 'Meta days are each ad account''s own day (Main = Los Angeles, BackUp = New York); Google, Upstack and orders are Pacific days.', 'The last 3-7 days still move (Meta restates), and today is never loaded.']::text[], 'marketing'),
  ('meta_purchases', 'Meta-reported purchases', 'sum(meta_purchases): purchases Meta reports for the ad that day (omni_purchase, else purchase, else pixel purchase), Meta''s default attribution.', 'analytics.meta_ad_daily.meta_purchases; analytics.meta_campaign_daily.meta_purchases', 'Meta-reported (counts returning customers, Meta''s attribution window)', ARRAY['Upstack new customers (analytics.meta_ad_daily.upstack_new_customers): first orders only', 'Upstack all orders (upstack_orders): every order Upstack credits']::text[], ARRAY['Never compare Upstack new customers with Meta''s all purchases: Meta counts returning customers, Upstack''s new-customer basis does not (they are different quantities, not one number measured twice).', 'Meta and Google credit the same orders: never add Meta purchases to Google''s.', 'Meta counts a returning customer''s order as a purchase; it is not a new customer.']::text[], 'marketing'),
  ('landing_page_views', 'Meta landing page views', 'sum(landing_page_views): landing page views Meta reports for the ad that day (omni_landing_page_view, else landing_page_view): clicks where the page actually loaded.', 'analytics.meta_ad_daily.landing_page_views', 'Meta-reported (default attribution), all ad accounts', ARRAY['Link clicks (analytics.meta_ad_daily.link_clicks): clicks before the page loads, always at least as large', 'Unique outbound clicks (analytics.meta_reach / meta_product_reach): de-duplicated per person, a different denominator']::text[], ARRAY['NULL (not 0) on days before the 2026-11-12 funnel backfill: sum only over rows where it is not NULL, and divide by the matching rows'' other columns.', 'LPV / link clicks is typically 70-95%: a lower share means slow pages or lost clicks, not fewer buyers.', 'Not comparable to Upstack site visitors (analytics.site_traffic_daily): different tracker.']::text[], 'marketing'),
  ('add_to_carts', 'Meta adds to cart', 'sum(add_to_carts): adds to cart Meta reports for the ad that day (omni_add_to_cart, else add_to_cart, else pixel add to cart), the ''Adds to cart'' of Ads Manager.', 'analytics.meta_ad_daily.add_to_carts', 'Meta-reported (default attribution, includes returning customers)', ARRAY['Meta purchases (analytics.meta_ad_daily.meta_purchases)']::text[], ARRAY['NULL (not 0) on days before the 2026-11-12 funnel backfill.', 'The funnel rates are ratios of sums over the same ad-days and rows: link click to add to cart = sum(add_to_carts) / sum(link_clicks); landing page view to add to cart = sum(add_to_carts) / sum(landing_page_views); add to cart to purchase = sum(meta_purchases) / sum(add_to_carts). Never average per-ad rates.', 'Purchases count returning customers, so add to cart to purchase is a Meta-attribution rate, not a new-customer conversion rate.']::text[], 'marketing'),
  ('initiated_checkouts', 'Meta initiated checkouts', 'sum(initiated_checkouts): checkouts Meta reports initiated for the ad that day (omni_initiated_checkout, else initiate_checkout, else pixel initiate checkout), the ''Checkouts initiated'' of Ads Manager.', 'analytics.meta_ad_daily.initiated_checkouts', 'Meta-reported (default attribution, includes returning customers)', ARRAY['Meta purchases (analytics.meta_ad_daily.meta_purchases)', 'Upstack orders (analytics.meta_ad_daily.upstack_orders): another tracker']::text[], ARRAY['NULL (not 0) on days before the checkout backfill: sum only over rows where it is not NULL, and divide only by sums over the same rows.', 'Funnel rates are ratios of sums over the same ad-days: add to cart to initiated checkout = sum(initiated_checkouts) / sum(add_to_carts); initiated checkout to purchase = sum(meta_purchases) / sum(initiated_checkouts); payment info to purchase = sum(meta_purchases) / sum(payment_info_adds). Never average per-ad rates.', 'Purchases count returning customers, so initiated checkout to purchase is a Meta-attribution rate, not a new-customer conversion rate. Checkout events fire on the pixel: a checkout that never loads the pixel (an in-app browser that blocks it) is not counted, so a fall in initiated checkouts is not proof of fewer checkouts.']::text[], 'marketing'),
  ('payment_info_adds', 'Meta payment info added', 'sum(payment_info_adds): payment-info-added events Meta reports for the ad that day (omni_add_payment_info, else add_payment_info, else pixel add payment info), the step between initiated checkout and purchase.', 'analytics.meta_ad_daily.payment_info_adds', 'Meta-reported (default attribution, includes returning customers)', ARRAY['Initiated checkouts (analytics.meta_ad_daily.initiated_checkouts)', 'Meta purchases (analytics.meta_ad_daily.meta_purchases)']::text[], ARRAY['NULL (not 0) on days before the checkout backfill.', 'It can exceed initiated checkouts on a day (a customer re-entering payment details, or express wallets that skip the initiate event): use it as a trend, not as a stage that must be smaller than the one before.', 'Same attribution as purchases, so it counts returning customers.']::text[], 'marketing'),
  ('atc_to_ic_rate', 'Add to cart to initiated checkout rate', 'sum(initiated_checkouts) / sum(add_to_carts): the share of adds to cart that go on to start checkout, as a ratio of sums over the same ad-days (Meta-reported).', 'analytics.meta_ad_daily.initiated_checkouts,add_to_carts', 'Meta-reported (default attribution, includes returning customers)', ARRAY['Link click to add to cart and landing page view to add to cart (see add_to_carts)']::text[], ARRAY['Restrict to rows where both columns are not NULL; never average per-ad rates.', 'Not a new-customer rate: Meta counts returning customers in both counts.']::text[], 'marketing'),
  ('ic_to_purchase_rate', 'Initiated checkout to purchase rate', 'sum(meta_purchases) / sum(initiated_checkouts): the share of started checkouts that Meta credits with a purchase, as a ratio of sums over the same ad-days (Meta-reported).', 'analytics.meta_ad_daily.meta_purchases,initiated_checkouts', 'Meta-reported (default attribution, includes returning customers)', ARRAY['Upstack new-customer orders per initiated checkout (upstack_new_customers / initiated_checkouts) mixes bases: say so if used', 'Add to cart to purchase (see add_to_carts)']::text[], ARRAY['Restrict to rows where initiated_checkouts is not NULL; never average per-ad rates.', 'Purchases use Meta''s attribution window and can land on a later day than the checkout, so a single day''s rate is noisy and the last days still move.']::text[], 'marketing'),
  ('meta_change_log', 'Meta change log (budget, bid, status, targeting changes)', 'count of rows in analytics.meta_change_log by event_type and event_day; budget and bid amounts in old_amount / new_amount (dollars). Ad set settings by day: analytics.meta_adset_state_daily; their day-over-day differences: analytics.meta_change_ledger.', 'analytics.meta_change_log.event_type,old_amount,new_amount', 'Meta activity log (read only), both ad accounts', ARRAY['Ad set snapshot differences (analytics.meta_change_ledger), from its first snapshot day: independent of the log''s extra_data']::text[], ARRAY['A change is not a cause: say ''a bid change on N ad sets preceded the move'', never ''the bid change caused it'', unless a control supports it.', 'The log''s extra_data is often incomplete for bids and caps; cross-check with analytics.meta_change_ledger, which only exists from its first snapshot day.', 'System events (first_delivery_event, Pending Review flips, billing, image adds) dominate the row count: filter to the event types you mean.', 'Campaign budget (CBO) changes are update_campaign_budget with object_level campaign; ad set budgets are update_ad_set_budget with object_level adset.']::text[], 'marketing'),
  ('meta_roas', 'Meta ROAS (platform ROAS)', 'sum(meta_revenue) / sum(spend): Meta-reported purchase value over spend, as a ratio of sums.', 'analytics.meta_ad_daily.meta_revenue,spend; analytics.meta_campaign_daily.meta_revenue,spend', 'Meta-reported purchase value / Meta spend', ARRAY['Upstack new-customer ROAS (upstack_nc_roas)', 'Upstack all-orders ROAS (upstack_all_orders_roas)', 'Total NC ROAS (total_nc_roas): actual new-customer revenue over total spend']::text[], ARRAY['Never average daily ROAS: divide the sums.', 'Meta ROAS counts returning customers and runs well above Total NC ROAS: they answer different questions.', 'Creative-level ROAS in analytics.creative_family_metrics / priorities_concepts is the same Meta-reported ratio but over each ad''s life since launch (blank under $100 spend in the priorities snapshot).']::text[], 'marketing'),
  ('meta_cpa', 'Meta cost per purchase', 'sum(spend) / sum(meta_purchases).', 'analytics.meta_ad_daily.spend,meta_purchases', 'Meta-reported purchases', ARRAY['Upstack new-customer CPA over Meta spend (spend / upstack_new_customers)', 'Total NC CPA (nc_cpa): total spend / actual new customers']::text[], ARRAY['Never compare Upstack new customers with Meta''s all purchases: Meta counts returning customers, Upstack''s new-customer basis does not (they are different quantities, not one number measured twice).', 'This is not the NC CPA the business quotes (that one divides by actual new customers, see nc_cpa).']::text[], 'marketing'),
  ('upstack_new_customers', 'Upstack-attributed new customers', 'sum(upstack_new_customers): first-time customers Upstack credits to the ad under any-click, 30-day attribution (utm_source ''Meta Ads'').', 'analytics.meta_ad_daily.upstack_new_customers; analytics.google_campaign_daily.upstack_new_customers', 'Upstack new customers (first orders only, any-click 30-day, Pacific days)', ARRAY['Upstack all orders (upstack_orders): every order credited, returning included', 'Last-click by source (analytics.attribution_source_daily): exclusive per order, a different basis']::text[], ARRAY['NULL, not 0, on days Upstack was not pulled (Meta before 2026-05-06, Google before 2025-05-13).', 'Any-click credits an ad on days it spent nothing (spend = 0, upstack_* > 0 is normal); one customer can be credited to several ads, so sums over ads of different families can exceed orders_daily.new_customers.', 'About 1.3% of credited orders match no Meta ad (analytics.attribution_unmapped_daily): in orders_daily, in no ad row.', 'Never compare Upstack new customers with Meta''s all purchases: Meta counts returning customers, Upstack''s new-customer basis does not (they are different quantities, not one number measured twice).']::text[], 'attribution'),
  ('upstack_nc_roas', 'Upstack new-customer ROAS (attributed)', 'sum(upstack_new_customer_revenue) / sum(spend) over the rows where Upstack was pulled (upstack_new_customers IS NOT NULL).', 'analytics.meta_ad_daily.upstack_new_customer_revenue,spend; analytics.google_campaign_daily.upstack_new_customer_revenue,spend', 'Upstack new customers (the default basis everywhere in the Marketing metrics app: ''Count: New customers'')', ARRAY['Upstack all orders (upstack_all_orders_roas)', 'Meta-reported (meta_roas)']::text[], ARRAY['Never compare Upstack new customers with Meta''s all purchases: Meta counts returning customers, Upstack''s new-customer basis does not (they are different quantities, not one number measured twice).', 'Restrict spend to days Upstack covers or the ratio is diluted by uncovered days.', 'When one ad is copied into several ad sets under one name, Upstack''s credit is split by Meta spend that day: family and higher sums are exact, one copy''s own numbers are an allocation.', 'Attribution, not the actual: the business''s real new-customer revenue is orders_daily (see nc_revenue / total_nc_roas).']::text[], 'attribution'),
  ('upstack_all_orders_roas', 'Upstack all-orders ROAS (attributed)', 'sum(upstack_order_revenue) / sum(spend) over the rows where Upstack was pulled.', 'analytics.meta_ad_daily.upstack_order_revenue,spend; analytics.google_campaign_daily.upstack_order_revenue,spend', 'Upstack all orders (every order Upstack credits to the ad, any-click 30 days)', ARRAY['Upstack new customers (upstack_nc_roas): the default basis', 'Meta-reported (meta_roas)']::text[], ARRAY['Use this only against Meta''s all-purchases basis, never against upstack_nc_roas.', 'Includes returning customers'' orders, so it flatters acquisition efficiency; the Marketing metrics app shows it only when ''Count: All orders'' is chosen.']::text[], 'attribution'),
  ('nc_revenue', 'New-customer revenue (actual)', 'sum(new_customer_revenue): first-order revenue per Pacific day, counted once (Upstack order-level measures).', 'analytics.orders_daily.new_customer_revenue; analytics.orders_by_product_daily.new_customer_revenue', 'Actual orders feed (analytics.orders_daily), gross: tax included, before refunds', ARRAY['By product (analytics.orders_by_product_daily): order total split across product lines by net line price', 'Attributed to Meta or Google (upstack_new_customer_revenue): an attribution, not the actual']::text[], ARRAY['Not the sum of platform columns: platforms overlap, this is counted once.', 'A day with no orders is absent from orders_daily, not 0.', 'Revenue is gross of tax and refunds (the Marketing metrics app describes it as ''tax included, before refunds''); net = total_revenue - tax - refunds in analytics.orders_daily_detail.', 'The trailing 7 days are restated nightly.']::text[], 'orders'),
  ('nc_orders', 'New customers (actual)', 'sum(new_customers): customers whose first Shopify order fell on the day, counted once.', 'analytics.orders_daily.new_customers; analytics.orders_by_product_daily.new_customers', 'Actual orders feed (analytics.orders_daily)', ARRAY['By product (orders whose largest product line is the product)', 'Upstack-attributed new customers (upstack_new_customers)']::text[], ARRAY['Not additive with attributed new customers: those credit the same customer to several ads or platforms.', 'Customers, not orders: a first order is the unit.']::text[], 'orders'),
  ('total_nc_roas', 'Total NC ROAS', 'sum(orders_daily.new_customer_revenue) / (sum(Meta spend) + sum(Google spend)) over the days that Meta, Google and orders_daily all cover, as a ratio of sums.', 'analytics.orders_daily.new_customer_revenue; analytics.platform_daily.spend', 'Actual new-customer revenue / Meta + Google spend (app/trends.py build_catalog(), nc_roas)', ARRAY['NC ROAS on Meta spend alone (meta_nc_roas in app/trends.py build_catalog()): the product bands'' Total column', 'Business-wide NC ROAS in pacing = (Shopify + Amazon new-customer revenue) / (Meta + Google + TikTok + other + Amazon ads) (app/projection/pacing/catalog.py, biz_nc_roas)', 'Per-product NC ROAS = analytics.orders_by_product_daily revenue / analytics.meta_product_daily spend']::text[], ARRAY['The numerator is actual revenue counted once, not the sum of the platforms'' purchase values.', 'Use only days all three sources cover and compute the ratio of sums, never an average of daily ratios.', 'Gross revenue (tax included, before refunds); the deal''s net-of-tax goal basis is lower.', 'Amazon is not in this ratio (the Marketing metrics app''s total covers Shopify, Meta and Google).']::text[], 'orders'),
  ('nc_cpa', 'NC CPA (cost per new customer)', '(sum(Meta spend) + sum(Google spend)) / sum(orders_daily.new_customers), over the days all three sources cover.', 'analytics.platform_daily.spend; analytics.orders_daily.new_customers', 'Total spend / actual new customers (app/trends.py build_catalog(), nc_cpa)', ARRAY['Meta spend / actual new customers (meta_nc_cpa): the product bands'' Total column', 'Testing / scaling NC CPA = stage spend / any-click new customers of that stage (analytics.attribution_anyclick_daily)', 'Upstack-attributed NC CPA = spend / upstack_new_customers (a different, attributed basis)']::text[], ARRAY['Divides by ACTUAL new customers, not by attributed ones or by Meta purchases.', 'Per-product NC CPA counts new customers whose largest product line is the product (analytics.orders_by_product_daily).']::text[], 'orders'),
  ('mer', 'MER (marketing efficiency ratio)', 'sum(total_revenue) / (sum(Meta spend) + sum(Google spend)) over the days all three sources cover.', 'analytics.orders_daily.total_revenue; analytics.platform_daily.spend', 'Orders feed total revenue (no Amazon) / Meta + Google spend (app/trends.py build_catalog(), mer)', ARRAY['Business-wide MER in pacing adds Amazon revenue and Amazon / TikTok / other spend (app/projection/pacing/catalog.py, biz_mer)']::text[], ARRAY['Total revenue here is gross (tax included, before refunds) and has no Amazon revenue; the matching spend has no Amazon or TikTok spend.']::text[], 'orders'),
  ('conversion_rate_uoc', 'Conversion rate on unique outbound clicks', 'actual new customers / Meta unique outbound clicks: per product = orders_by_product_daily.new_customers / meta_product_reach.unique_outbound_clicks; total = orders_daily.new_customers / meta_reach.unique_outbound_clicks.', 'analytics.orders_by_product_daily.new_customers; analytics.meta_product_reach.unique_outbound_clicks; analytics.orders_daily.new_customers; analytics.meta_reach.unique_outbound_clicks', 'Actual new customers / unique outbound clicks (app/projection/pacing/catalog.py, meta_cvr_<product> and prod_cvr_total; every click-based pacing metric uses UNIQUE OUTBOUND clicks)', ARRAY['Meta CVR = Meta purchases / Meta link clicks (meta_cvr)', 'NC conversion (clicks) = new customers / (Meta link clicks + Google clicks) (app/trends.py build_catalog(), nc_cvr_clicks)', 'NC conversion (visitors) = new customers / Upstack new visitors (analytics.site_traffic_daily): the Marketing metrics app''s nc_cvr']::text[], ARRAY['Unique outbound clicks exist only from 2026-07-05 (Meta serves filtered unique clicks ~120 days back); earlier periods are blank, not 0.', 'Unique clicks are not additive: read the row of the period''s own grain (day, week or month) in meta_reach / meta_product_reach.', 'The three products'' unique clicks add to 1.01-1.06x the account-level figure, so the product rates do not average to the total.', 'Meta''s total link_click count (analytics.meta_ad_daily.link_clicks) is a different, larger denominator than unique outbound clicks: do not mix the two.']::text[], 'marketing'),
  ('cpm', 'CPM (cost per 1,000 impressions)', 'sum(spend) / sum(impressions) x 1000.', 'analytics.meta_ad_daily.spend,impressions; analytics.meta_reach.impressions', 'Meta spend / Meta impressions x 1000 (app/trends.py build_catalog(), m_cpm)', ARRAY['Pacing divides spend by the account-level impressions pulled at the period''s own grain (app/projection/pacing/catalog.py, meta_cpm)', 'Cost per 1,000 reached = spend / reach x 1000 (a different, higher number)']::text[], ARRAY['Impressions add across days, reach does not: for CPM either source works, for frequency only meta_reach.', 'Meta days are the ad account''s own day.']::text[], 'marketing'),
  ('frequency', 'Frequency', 'impressions / reach, both taken at the SAME grain (a day''s, a week''s or a month''s own row): analytics.meta_reach.frequency.', 'analytics.meta_reach.impressions,reach,frequency', 'Account level, both ad accounts, at the grain you read (app/projection/pacing/catalog.py, meta_frequency)', ARRAY['No frequency exists per ad, ad set, campaign or product (reach is account level only)']::text[], ARRAY['Reach is de-duplicated by Meta and NOT additive: never average daily frequencies or sum daily reach to get a week or month; use the week / month rows.', 'The current day, week and month are partial.', 'Frequency here is the same-day overlap between ad sets, not exposure on more days.']::text[], 'marketing'),
  ('hit_rate', 'Creative hit rate', 'Display hit rate = ads whose since-launch spend reached $10,000 / launched ads (first tracker rows of an ad family with a launch date or any spend). Scoring hit rate = mature (>= 14 days old) judged ads (>= $100 spent) that reached $1,000 / mature judged ads, shrunk toward the product average.', 'analytics.creative_family_metrics.spend_launch,is_first_row,launch_date; analytics.priorities_concepts.ads_10k_plus_spend,ads_launched,hit_rate', 'Display: $10,000 since-launch spend over launched ads, Meta basis (etl/creative_priorities.py TOP_SPEND = 10000; the definition of a hit since 2026-11-10, docs/CREATIVE_PRIORITIES.md)', ARRAY['Scoring: HIT_SPEND = $1,000 over mature judged ads (priorities_concepts.hit_rate, hit_rate_index): the stored hit_rate in the snapshot and in the CSV export''s hit_rate / hit_rate_index columns', 'Hits out of tested ads: $10,000 / ads that spent $100 or more (hit_rate_10k_of_tested)']::text[], ARRAY['A KNOWN SPLIT: the displayed hit rate uses $10,000, but the priorities CSV export''s hit_rate and hit_rate_index columns (and the score''s hit-rate component) still use $1,000 (etl/creative_priorities.py: HIT_SPEND vs TOP_SPEND; docs/CREATIVE_PRIORITIES.md). Name which one you quote.', 'Launched counts every launched ad including recent ones with $0 spend; new ads need time to reach $10,000, so young cohorts read low.', 'Metrics sit on the FIRST tracker row of each ad family: filter is_first_row.']::text[], 'creative'),
  ('test_to_scale_rate', 'Test-to-scale rate (% reached scaling)', 'creatives that moved / creatives that began in testing, among creatives launched in the window and not launched before the data starts: count(*) FILTER (WHERE moved) / count(*) WHERE began_in_testing AND NOT launched_before_data_start AND first_day in window.', 'analytics.creative_stage_moves.moved,began_in_testing,launched_before_data_start,first_day,days_in_test', 'Meta basis (analytics.creative_stage_moves.basis = ''meta''); the basis changes only the money columns, never who moved (app/promotions.py _cohorts / build)', ARRAY['upstack_new_customers and upstack_all_orders: same creatives and moves, Upstack purchases and revenue']::text[], ARRAY['A creative MOVED only when it spent in a Testing campaign and first spent in a Scaling campaign on a LATER day (a campaign is Testing when its name contains ''test'').', 'Hide bulk days: 40 or more creatives entering scaling on one day (moves_that_day >= 40) is a mass relaunch, not a set of test winners.', 'Creatives that launched straight into scaling are not testers and never in the rate; a new creative needs time to move (analytics.creative_stage_moves.days_in_test): recent cohorts read low.', '''Held up'' = (scale_revenue / scale_spend) / (test_revenue / test_spend): held >= 0.90, softer >= 0.70, fell below; too early before $200 and 3 days in scaling.']::text[], 'creative'),
  ('repeat_revenue', 'Repeat revenue', 'Modeled: sum over cohorts of first-order revenue x curve[age] in the month at that age (age 0 = the acquisition month has no repeat): max(0, new_customers x first_order_per_customer x curve[age]) (app/projection/cohorts/engine.py repeat_for).', 'analytics.cohorts_monthly.first_order_revenue; analytics.cohorts_curve_cumulative.increment_ratio; analytics.cohorts_curve_goal.value', 'Modeled from the cohort table and the chosen retention curve (Live or Goal; scenario lever cohorts.curve_source in analytics.projection_levers)', ARRAY['Actual returning revenue = analytics.orders_daily.returning_customer_revenue (Upstack, gross)', 'Business-wide repeat = Shopify returning revenue + Amazon revenue not from new customers (app/projection/pacing/catalog.py, biz_repeat_rev)', 'Historical months come from the books (analytics.projection_actuals ''pnl.repeat_rev''); the model only projects forward']::text[], ARRAY['Repeat revenue is a projection driven by the curve choice; always say which curve (Live last N cohorts, Goal snapshot, as-of month).', 'The cohort table must hold only CLOSED months: a cell that lands in a month that is not over is blanked.', 'Gross of tax and refunds, like all pacing revenue.']::text[], 'cohorts'),
  ('retention_curve', 'Retention curve (Live vs Goal)', 'Repeat dollars per $1 of first-order revenue by age (months after acquisition). Live at age a = weighted average (weights new customers) of increment / first_order over the newest N cohorts that have a non-blank, non-zero increment at that age (usable_rank <= N); from age 28 on = previous age x 0.95. Goal = the newest saved snapshot of analytics.cohorts_curve_goal.', 'analytics.cohorts_curve_cumulative.increment_ratio,new_customers,usable_rank; analytics.cohorts_curve_goal.value,age,is_active', 'Live curve over the last 3 cohorts (app/projection/cohorts/engine.py Levers.n_cohorts = 3, tail_decay 0.95, tail_from_age 28)', ARRAY['Live over the last 6 cohorts (the P&L page offers 3 or 6; the deal notes mention 6; scenario lever cohorts.n_cohorts)', 'Goal curve (analytics.cohorts_curve_goal, is_active)', 'As-of curve: the Live curve re-derived from what was observable at the end of a past month', 'Blend: w x Goal + (1 - w) x Live']::text[], ARRAY['Say Live or Goal and N: the lifetime sums differ (compare sum(value) of the Goal curve with the Live curve you compute).', 'Never include a month that is not over; cohort exports differ by source (Shopify cohort dollars vs Upstack''s), so do not mix sources between refreshes.', 'Ages beyond 36 are the tail formula, not data.']::text[], 'cohorts'),
  ('payback', 'Payback (months)', 'First age (months after the first order, 0 = the first order pays) where cumulative contribution per new customer >= CAC. Inputs (aov, cac, product_cost_pct, fulfillment, max_age, curve) = analytics.projection_levers where module = ''financing'' and lever = ''payback'' (a json object holding only what the scenario sets; unset keys take the code defaults in app/projection/financing/params.py: product_cost_pct 0.1726, fulfillment 5.53, max_age 36, curve ''live''; aov and cac default to None = not typed). Contribution of the first order cm = AOV x (1 - product cost %) - fulfillment per order; month k adds cm x curve[k]; cumulative = cm + sum cm x curve.', 'analytics.projection_levers.module,lever,value; analytics.cohorts_curve_cumulative.increment_ratio; analytics.cohorts_monthly.cac,payback_months', 'Product margin: cost per order = product cost % x AOV + fulfillment (app/projection/financing/calc.py payback(); the quick hint app/projection/drivers/payback.py is the same arithmetic)', ARRAY['Fully loaded (''all variable costs''): cost per order = loaded_rate x AOV with the P&L''s own product, fulfillment, shipping, payment and chargeback rates (fully_loaded=True)', 'Interpolated months (months_interpolated) between the last unpaid and the first paid age', 'cohorts_monthly.payback_months: the payback exported with each cohort (a different, historical measure)']::text[], ARRAY['Payback on product margin is much shorter than fully loaded: always name the basis.', 'The curve behind it (Live N cohorts vs Goal) moves the answer by a month at some scales.', 'Contribution, not revenue: do not compare cumulative revenue with CAC.']::text[], 'cohorts'),
  ('gross_vs_net_revenue', 'Gross vs net revenue (pacing is gross)', 'Gross = total_revenue (tax included, before refunds). Net = total_revenue - tax - refunds. Plan basis = total_revenue - the plan''s sales-tax estimate (+ Amazon).', 'analytics.orders_daily.total_revenue; analytics.orders_daily_detail.total_revenue,tax,refunds', 'Gross: the pacing page, the P&L and every ROAS / MER here are gross; refunds are a memo row only (decision 2026-11-04)', ARRAY['Net of tax and refunds (app/projection/pacing/catalog.py, biz_total_rev_net)', 'Plan basis: Shopify total less the sales-tax estimate, plus Amazon: the basis of the P&L revenue goal (biz_total_rev_plan)']::text[], ARRAY['The monthly plan block and Month Snapshot compare against the P&L goal, which is net of the estimated sales tax (docs/projection/MODULE_pacing.md): comparing gross Shopify revenue with that goal overstates pacing.', 'Refunds are not deducted anywhere unless you subtract them (net = gross - tax - refunds): refunds were 11% of DTC revenue in Nov 1-2, so a net-of-refunds basis paced about 101% of goal, not 106% (docs/projection/MODULE_pacing.md, open items).']::text[], 'orders'),
  ('sales_tax_deduction', 'Sales-tax deduction (estimate)', 'Sales tax(m) = 0 for a month whose DTC revenue is loaded from the books (already net of tax), else -(sales_tax_rate x DTC revenue(m)); sales_tax_rate = analytics.projection_levers where module = ''drivers'' and lever = ''sales_tax_rate''; no row means the code default 0.07. It reduces total revenue.', 'analytics.projection_levers.module,lever,value; analytics.orders_daily_detail.tax', 'Estimate: 7% of DTC revenue for months not yet closed in the books (app/projection/drivers/revenue.py, drivers/model.py DEFAULT_SALES_TAX)', ARRAY['Actual tax collected (analytics.orders_daily_detail.tax), used by pacing''s net view', 'Closed books months carry no deduction']::text[], ARRAY['Open question (docs/projection/SKEPTIC_REPORT.md, SHEET_FINDINGS.md S1): the deduction applies from Jul-26 while history months carry none and the DTC revenue behind it is already net of tax; removing it adds about $535K to FY27 NOI. Settle against the Aug QuickBooks close or set drivers.sales_tax_rate to 0.', 'DTC rows of the pacing page stay gross on purpose; only the goal / projection total is net of the estimate.']::text[], 'projection'),
  ('repeat_share', 'Repeat share of revenue', 'sum(returning_customer_revenue) / sum(total_revenue).', 'analytics.orders_daily.returning_customer_revenue,total_revenue', 'Actual orders feed, Shopify only (app/trends.py build_catalog(), repeat_share)', ARRAY['Business-wide: (Shopify returning + Amazon non-new-customer revenue) / (Shopify + Amazon revenue) (app/projection/pacing/catalog.py, biz_repeat_share)']::text[], ARRAY['Gross of tax and refunds; no Amazon in the Shopify-only ratio.']::text[], 'orders')
) AS g(name, label, formula, source, default_basis, other_bases, traps, domain);

COMMENT ON VIEW analytics.meta_ad_daily IS 'The main Meta fact view: one row per Meta ad per day with Meta-reported results AND Upstack-attributed new customers / orders side by side, plus the ad''s names, campaign, ad set, stage and product. Roll up from here; never add purchases to Google''s. Grain: one row per (day, ad_id). Source: public.ad_daily (Meta Graph API, ad x day) combined per ad and day with public.ad_daily_upstack (Upstack any-click 30-day attribution mapped to ads), names from analytics.meta_ads. Refresh: nightly (etl service 13:00 UTC): Meta trailing 28 days re-pulled and replaced (Meta restates conversions for weeks), Upstack trailing 7 days re-pulled. Coverage: 2026-05-06 through yesterday (Pacific). Meta days are each ad account''s own calendar day; Upstack days are Pacific.. Caveats: Three bases live in this view. spend, impressions, link_clicks, meta_purchases, meta_revenue are Meta''s. upstack_new_customers / upstack_new_customer_revenue are Upstack''s first-order basis (the ''NC'' numbers: NC ROAS = upstack_new_customer_revenue / spend). upstack_orders / upstack_order_revenue are every order Upstack credits to the ad. Spend is Meta''s in all three. | upstack_* is NULL (not 0) on days Upstack has not been pulled; coverage starts 2026-05-06 as well. | Upstack credits an order to every ad clicked in the 30 days before it (any-click), so Upstack-only ad-days exist where the ad spent nothing that day (spend = 0, meta_* = 0, upstack_* > 0). Filter spend > 0 only if you want delivery days. | When one ad is copied into several ad sets under the same name, Upstack (which sees names, not ids) credit is split across the copies by their Meta spend that day. Family-level and higher sums are exact; one copy''s own upstack_* numbers are an allocation. | About 1.3% of Upstack-credited orders and 1.3% of new customers match no Meta ad (''(not set)'', deleted ads); they are in orders_daily but in no row here. | Meta purchases count returning customers; Upstack new customers do not. They are different quantities, not the same number measured twice. | link_clicks is Meta''s ''link_click'' action count (link clicks, not all clicks). Impressions are Meta''s. | source: ''meta_api'' for Graph-pulled rows, ''sheet'' for the old family-grain backfill (none left in production), NULL on Upstack-only ad-days.';
COMMENT ON COLUMN analytics.meta_ad_daily.day IS 'Calendar day. Meta numbers: the ad account''s own day (Main = America/Los_Angeles, BackUp = America/New_York, not re-based). Upstack numbers: Pacific.';
COMMENT ON COLUMN analytics.meta_ad_daily.ad_id IS 'Meta ad id.';
COMMENT ON COLUMN analytics.meta_ad_daily.ad_name IS 'Current ad name.';
COMMENT ON COLUMN analytics.meta_ad_daily.product_slug IS 'Product the ad counts under (see analytics.meta_ads); NULL = no active product.';
COMMENT ON COLUMN analytics.meta_ad_daily.campaign_id IS 'Meta campaign id (NULL on family-grain legacy rows).';
COMMENT ON COLUMN analytics.meta_ad_daily.campaign_name IS 'Campaign name.';
COMMENT ON COLUMN analytics.meta_ad_daily.stage IS '''testing'' | ''scaling'' from the campaign name (''test'' in the name = testing).';
COMMENT ON COLUMN analytics.meta_ad_daily.adset_id IS 'Meta ad set id (NULL on family-grain legacy rows).';
COMMENT ON COLUMN analytics.meta_ad_daily.adset_name IS 'Ad set name.';
COMMENT ON COLUMN analytics.meta_ad_daily.account IS '''Lonvera Main'' or ''Lonvera BackUp''.';
COMMENT ON COLUMN analytics.meta_ad_daily.source IS 'Where the Meta side of the row came from: ''meta_api'' | ''sheet''; NULL when the row exists only because Upstack credited the ad.';
COMMENT ON COLUMN analytics.meta_ad_daily.spend IS 'Meta spend, dollars (0 on Upstack-only ad-days). Additive across ads, ad sets, campaigns and across platforms.';
COMMENT ON COLUMN analytics.meta_ad_daily.impressions IS 'Meta impressions.';
COMMENT ON COLUMN analytics.meta_ad_daily.link_clicks IS 'Meta link clicks.';
COMMENT ON COLUMN analytics.meta_ad_daily.meta_purchases IS 'Purchases Meta reports for the ad that day (omni_purchase, else purchase, else pixel purchase), Meta''s default attribution; includes returning customers.';
COMMENT ON COLUMN analytics.meta_ad_daily.meta_revenue IS 'Purchase conversion value Meta reports, dollars. meta_revenue / spend = Meta ROAS.';
COMMENT ON COLUMN analytics.meta_ad_daily.upstack_new_customers IS 'First-time customers Upstack credits to the ad (any-click, 30-day window, utm_source ''Meta Ads''). NULL on days not pulled.';
COMMENT ON COLUMN analytics.meta_ad_daily.upstack_new_customer_revenue IS 'Order total (tax included, before refunds) of those first orders, dollars. / spend = NC ROAS.';
COMMENT ON COLUMN analytics.meta_ad_daily.upstack_orders IS 'All orders (new and returning customers) Upstack credits to the ad. NULL on days not pulled.';
COMMENT ON COLUMN analytics.meta_ad_daily.upstack_order_revenue IS 'Order total of those orders, dollars (tax included, before refunds).';
COMMENT ON COLUMN analytics.meta_ad_daily.landing_page_views IS 'Meta landing page views (omni_landing_page_view, else landing_page_view). NULL when the day has no Meta pull of it yet; 0 on Upstack-only ad-days.';
COMMENT ON COLUMN analytics.meta_ad_daily.add_to_carts IS 'Meta adds to cart (omni_add_to_cart, else add_to_cart, else pixel add to cart), the ''Adds to cart'' of Ads Manager; includes returning customers. NULL when not pulled yet; 0 on Upstack-only ad-days.';
COMMENT ON COLUMN analytics.meta_ad_daily.initiated_checkouts IS 'Meta initiated checkouts (omni_initiated_checkout, else initiate_checkout, else pixel initiate checkout), the ''Checkouts initiated'' of Ads Manager; includes returning customers. NULL when not pulled yet; 0 on Upstack-only ad-days.';
COMMENT ON COLUMN analytics.meta_ad_daily.payment_info_adds IS 'Meta payment info added (omni_add_payment_info, else add_payment_info, else pixel add payment info), the checkout step between initiated checkout and purchase. NULL when not pulled yet; 0 on Upstack-only ad-days.';
COMMENT ON TABLE public.ad_daily IS 'Meta Graph API results per ad per day: the base fact table behind every Meta number. Meta-reported (Meta''s own attribution). Grain: one row per (ad_id, day). Source: Meta Graph API insights level=ad, time_increment=1, both ad accounts (Lonvera Main, Lonvera BackUp); written by etl.meta_pull. Refresh: nightly (etl service 13:00 UTC, etl.run_daily): the trailing 28 days are re-pulled and replaced in ONE transaction (all or nothing), because Meta restates conversions for weeks. Coverage: 2026-05-06 (app_meta.daily_start, never moves) through yesterday; about 135K rows, 18.7K distinct ads in production. Caveats: day is the ad account''s OWN calendar day (Main = America/Los_Angeles, BackUp = New York); not re-based. | purchases = Meta action omni_purchase, else purchase, else offsite_conversion.fb_pixel_purchase, under Meta''s default attribution (no window is requested); it counts returning customers. conv_value is the matching action value. Neither is Upstack''s new-customer number. | No row filter on spend: purchases booked on days without delivery are kept, so a row can have spend 0 and purchases > 0. | link_clicks is Meta''s link_click action (fallback inline_link_clicks). impressions is NULL only on legacy sheet rows (none in production). | landing_page_views = action omni_landing_page_view (else landing_page_view); add_to_carts = omni_add_to_cart (else add_to_cart, else offsite_conversion.fb_pixel_add_to_cart), same Meta default attribution as purchases. Both are NULL (not 0) on days before they were first pulled; the 2026-11-12 backfill fills them without touching any other column. | initiated_checkouts = omni_initiated_checkout (else initiate_checkout, else offsite_conversion.fb_pixel_initiate_checkout); payment_info_adds = omni_add_payment_info (else add_payment_info, else the pixel event; Meta returns only add_payment_info today). Both NULL (not 0) before the checkout backfill filled them (fill-only, no other column touched). | meta_family_key / meta_family follow the ad''s CURRENT name (build_metrics re-syncs them after a rename). | Rows with source ''sheet'' / ad_id ''fam:<family>'' were a family-grain backfill; none remain in production. | Reach, frequency, video metrics (thruplays, watch time), demographic / placement breakdowns, ad-level budgets and bids are NOT stored.';
COMMENT ON COLUMN public.ad_daily.ad_id IS 'Meta ad id (text). ''fam:<family key>'' on legacy family-grain rows.';
COMMENT ON COLUMN public.ad_daily.day IS 'Calendar day in the ad account''s own timezone.';
COMMENT ON COLUMN public.ad_daily.meta_family_key IS 'lower(ad family): ad name without '' - Copy N'' / merge-tag suffixes. Joins meta_family_map.';
COMMENT ON COLUMN public.ad_daily.meta_family IS 'The ad family with its original case.';
COMMENT ON COLUMN public.ad_daily.campaign_id IS 'Meta campaign id ('''' = unknown, legacy rows only).';
COMMENT ON COLUMN public.ad_daily.spend IS 'Meta spend, dollars.';
COMMENT ON COLUMN public.ad_daily.purchases IS 'Meta-reported purchases (omni_purchase > purchase > pixel purchase), Meta default attribution; includes returning customers.';
COMMENT ON COLUMN public.ad_daily.conv_value IS 'Meta-reported purchase conversion value, dollars (revenue for Meta ROAS).';
COMMENT ON COLUMN public.ad_daily.link_clicks IS 'Meta link clicks.';
COMMENT ON COLUMN public.ad_daily.source IS '''meta_api'' | ''sheet''.';
COMMENT ON COLUMN public.ad_daily.loaded_at IS 'When the row was written.';
COMMENT ON COLUMN public.ad_daily.impressions IS 'Meta impressions (NULL = unknown, legacy rows).';
COMMENT ON COLUMN public.ad_daily.landing_page_views IS 'Meta landing page views (omni_landing_page_view, else landing_page_view). NULL = not pulled yet (days before the 2026-11-12 funnel backfill).';
COMMENT ON COLUMN public.ad_daily.add_to_carts IS 'Meta adds to cart (omni_add_to_cart, else add_to_cart, else pixel add to cart), the ''Adds to cart'' of Ads Manager. NULL = not pulled yet.';
COMMENT ON COLUMN public.ad_daily.initiated_checkouts IS 'Meta initiated checkouts (omni_initiated_checkout, else initiate_checkout, else pixel initiate checkout). NULL = not pulled yet.';
COMMENT ON COLUMN public.ad_daily.payment_info_adds IS 'Meta payment info added (omni_add_payment_info, else add_payment_info, else pixel add payment info). NULL = not pulled yet.';
COMMENT ON TABLE public.meta_ad_lifetime IS 'All-time Meta totals per ad (Meta-reported), the source of every ''since launch'' number. Grain: one row per ad_id. Source: Meta Graph API insights level=ad over the whole account life (etl.lifetime_pull), both accounts. Refresh: nightly (etl.run_daily): the table is REPLACED as a whole, only when both accounts reconcile with account-level lifetime spend within 0.5%. Coverage: 41.7K ads, through the last complete day. Caveats: Totals cover the ad''s whole life, which reaches back before ad_daily''s 2026-05-06 start. | tracker_family_key is only filled on legacy sheet-sourced rows; use meta_family_map for the tracker match. source is ''meta_api'' for every production row. | Meta-reported (default attribution); purchases include returning customers.';
COMMENT ON COLUMN public.meta_ad_lifetime.ad_id IS 'Meta ad id.';
COMMENT ON COLUMN public.meta_ad_lifetime.meta_family_key IS 'lower(ad family), re-synced to the ad''s current name.';
COMMENT ON COLUMN public.meta_ad_lifetime.tracker_family_key IS 'Legacy: the sheet tab''s Ad Family column (NULL for API rows).';
COMMENT ON COLUMN public.meta_ad_lifetime.spend IS 'All-time spend, dollars.';
COMMENT ON COLUMN public.meta_ad_lifetime.purchases IS 'All-time Meta-reported purchases.';
COMMENT ON COLUMN public.meta_ad_lifetime.conv_value IS 'All-time Meta-reported purchase value, dollars.';
COMMENT ON COLUMN public.meta_ad_lifetime.impressions IS 'All-time impressions.';
COMMENT ON COLUMN public.meta_ad_lifetime.link_clicks IS 'All-time link clicks.';
COMMENT ON COLUMN public.meta_ad_lifetime.source IS '''meta_api'' (production) | ''sheet'' (legacy).';
COMMENT ON COLUMN public.meta_ad_lifetime.pulled_at IS 'When the all-time pull ran.';
COMMENT ON COLUMN public.meta_ad_lifetime.first_day IS 'Earliest delivery day if known (legacy).';
COMMENT ON COLUMN public.meta_ad_lifetime.landing_page_views IS 'All-time Meta landing page views (omni_landing_page_view, else landing_page_view). NULL until the next nightly lifetime pull.';
COMMENT ON COLUMN public.meta_ad_lifetime.add_to_carts IS 'All-time Meta adds to cart (omni_add_to_cart, else add_to_cart, else pixel add to cart). NULL until the next nightly lifetime pull.';
COMMENT ON COLUMN public.meta_ad_lifetime.initiated_checkouts IS 'All-time Meta initiated checkouts (omni_initiated_checkout, else initiate_checkout, else pixel initiate checkout). NULL until the next nightly lifetime pull.';
COMMENT ON COLUMN public.meta_ad_lifetime.payment_info_adds IS 'All-time Meta payment info added (omni_add_payment_info, else add_payment_info, else pixel add payment info). NULL until the next nightly lifetime pull.';
COMMENT ON TABLE public.meta_change_log IS 'The Meta Marketing API activity log of both ad accounts: one row per change event (budget, bid, bid strategy, status, targeting, optimization goal, name, creation, creative, billing), who made it and when. Grain: one row per activity-log event (event_key = sha1 of account, event_time, event_type, object_id, extra_data, actor_id: Meta gives no event id). Source: Meta Marketing API GET /act_<id>/activities (read only), etl.meta_changes. Refresh: nightly in the etl run: the last 3 days re-read (overlap, deduped); history was backfilled week by week. Coverage: the backfill start is in docs (see analytics.data_coverage / min(event_day)); account BackUp has had no events in the loaded window unless rows say otherwise. Caveats: object_type is Meta''s old vocabulary: ADGROUP = an ad, CAMPAIGN = an ad SET, CAMPAIGN_GROUP = a campaign, ACCOUNT = the ad account; object_level carries the plain word (ad, adset, campaign, account). | Budgets and bids come as minor units and are stored in dollars (old_amount / new_amount: daily or lifetime budget for the budget events, the bid cap or target for bid strategy events, the charge for billing events). The ROAS floor comes x10000 and is stored as a ratio (0.90 = a 0.90x floor). | extra_data is often incomplete for bids and caps (a change of a bid on an ad set with no strategy change can be missing): meta_adset_state_daily and analytics.meta_change_ledger are the cross-check, from their first snapshot day on. | Meta writes system events too: first_delivery_event (actor Meta), update_ad_run_status to or from Pending Review / Pending Process, billing charges. Filter on actor_name or event_type for human changes. | Two byte-identical events in the same second collapse to one row. add_images / edit_images keep no extra_data in raw (signed image URLs that expire).';
COMMENT ON COLUMN public.meta_change_log.id IS 'Surrogate row id.';
COMMENT ON COLUMN public.meta_change_log.event_key IS 'Stable dedupe key (sha1 of account, event_time, event_type, object_id, extra_data, actor_id).';
COMMENT ON COLUMN public.meta_change_log.account IS 'Lonvera Main or Lonvera BackUp.';
COMMENT ON COLUMN public.meta_change_log.event_time IS 'When Meta recorded the event (timestamptz).';
COMMENT ON COLUMN public.meta_change_log.event_day IS 'Pacific calendar day of event_time (America/Los_Angeles), the day grain every other Lonvera view uses.';
COMMENT ON COLUMN public.meta_change_log.event_type IS 'Meta''s event type, for example update_ad_set_budget, update_ad_set_bid_strategy, update_ad_set_run_status, update_ad_run_status, create_ad, create_ad_set, update_campaign_budget, update_ad_set_target_spec.';
COMMENT ON COLUMN public.meta_change_log.translated_event_type IS 'Meta''s human text for the event type (''Ad set budget updated'').';
COMMENT ON COLUMN public.meta_change_log.object_type IS 'Meta''s raw object type: ADGROUP (ad), CAMPAIGN (ad set), CAMPAIGN_GROUP (campaign), ACCOUNT.';
COMMENT ON COLUMN public.meta_change_log.object_level IS 'ad | adset | campaign | account (plain word for object_type).';
COMMENT ON COLUMN public.meta_change_log.object_id IS 'Id of the changed object (ad, ad set, campaign or ad account id, by object_level).';
COMMENT ON COLUMN public.meta_change_log.object_name IS 'Name of the object at the time of the event.';
COMMENT ON COLUMN public.meta_change_log.campaign_id IS 'Campaign of the object: the object itself for campaign events, extra_data.campaign_id for ad set and ad events (NULL when Meta did not send it).';
COMMENT ON COLUMN public.meta_change_log.actor_id IS 'Meta id of who made the change (0 = Meta itself).';
COMMENT ON COLUMN public.meta_change_log.actor_name IS 'Name of who made the change (''Meta'' for system events).';
COMMENT ON COLUMN public.meta_change_log.application_name IS 'App the change came through when Meta says (NULL otherwise).';
COMMENT ON COLUMN public.meta_change_log.old_value IS 'Text of the old value for scalar changes (status, strategy, name, goal, targeting description); NULL for amounts, which sit in old_amount.';
COMMENT ON COLUMN public.meta_change_log.new_value IS 'Text of the new value (same rules as old_value).';
COMMENT ON COLUMN public.meta_change_log.old_amount IS 'Old daily / lifetime budget or bid, dollars (budget and bid strategy events); NULL otherwise or when Meta did not send it.';
COMMENT ON COLUMN public.meta_change_log.new_amount IS 'New daily / lifetime budget or bid, dollars; for create_ad_set / create_campaign_group the starting budget; for billing events the amount charged.';
COMMENT ON COLUMN public.meta_change_log.old_roas_floor IS 'Old ROAS floor as a ratio (bid strategy events only).';
COMMENT ON COLUMN public.meta_change_log.new_roas_floor IS 'New ROAS floor as a ratio (bid strategy events only).';
COMMENT ON COLUMN public.meta_change_log.raw IS 'The event as Meta returned it (extra_data parsed to JSON); the source of truth when a parsed column is NULL.';
COMMENT ON COLUMN public.meta_change_log.loaded_at IS 'When the row was first written.';
COMMENT ON TABLE public.meta_adset_state_daily IS 'A nightly snapshot of every live ad set''s settings in both ad accounts (status, budget, bid, ROAS floor, optimization goal, attribution window): the record that lets a change in a bid or budget be seen even when the activity log''s extra_data is incomplete. Grain: one row per ad set per snapshot day (Pacific). Source: Meta Marketing API GET /act_<id>/adsets (read only), etl.meta_changes. Refresh: nightly in the etl run (~05:00 Pacific); a same-day rerun replaces that day''s rows. Coverage: starts on the day the first snapshot ran (see min(day)); nothing before it exists and it cannot be backfilled. Caveats: Live ad sets (any status except archived) every day; archived ad sets only on the days within 3 days of their last update, so the archive step is visible without 4,000 dead rows a day. | Under campaign budget optimization (CBO) the ad set has no budget of its own: daily_budget and lifetime_budget are NULL and the budget lives on the campaign (see meta_change_log update_campaign_budget). | bid_strategy is NULL on ad sets that inherit the strategy from a CBO campaign. | A missing day (the run did not happen) shows as a longer gap in analytics.meta_change_ledger (prev_day), never as a fake change.';
COMMENT ON COLUMN public.meta_adset_state_daily.adset_id IS 'Meta ad set id.';
COMMENT ON COLUMN public.meta_adset_state_daily.day IS 'Pacific day of the snapshot.';
COMMENT ON COLUMN public.meta_adset_state_daily.account IS 'Lonvera Main or Lonvera BackUp.';
COMMENT ON COLUMN public.meta_adset_state_daily.campaign_id IS 'Meta campaign id.';
COMMENT ON COLUMN public.meta_adset_state_daily.adset_name IS 'Ad set name on the snapshot day.';
COMMENT ON COLUMN public.meta_adset_state_daily.status IS 'Configured status: ACTIVE | PAUSED | ARCHIVED | DELETED.';
COMMENT ON COLUMN public.meta_adset_state_daily.effective_status IS 'Effective delivery status (ACTIVE, PAUSED, CAMPAIGN_PAUSED, ARCHIVED, IN_PROCESS, WITH_ISSUES): ACTIVE only when the ad set and its campaign are both on.';
COMMENT ON COLUMN public.meta_adset_state_daily.daily_budget IS 'Ad set daily budget, dollars (NULL under CBO).';
COMMENT ON COLUMN public.meta_adset_state_daily.lifetime_budget IS 'Ad set lifetime budget, dollars (NULL when not set).';
COMMENT ON COLUMN public.meta_adset_state_daily.bid_strategy IS 'LOWEST_COST_WITHOUT_CAP | COST_CAP | LOWEST_COST_WITH_BID_CAP | LOWEST_COST_WITH_MIN_ROAS ... (NULL when inherited from the campaign).';
COMMENT ON COLUMN public.meta_adset_state_daily.bid_amount IS 'Bid cap or cost-cap target, dollars (NULL when none).';
COMMENT ON COLUMN public.meta_adset_state_daily.roas_average_floor IS 'ROAS floor as a ratio (0.90 = 0.90x; Meta stores it x10000); NULL when none.';
COMMENT ON COLUMN public.meta_adset_state_daily.optimization_goal IS 'Meta optimization goal (OFFSITE_CONVERSIONS, VALUE, LINK_CLICKS ...).';
COMMENT ON COLUMN public.meta_adset_state_daily.attribution_spec IS 'Attribution windows as Meta returns them, for example [{"event_type": "CLICK_THROUGH", "window_days": 1}].';
COMMENT ON COLUMN public.meta_adset_state_daily.created_time IS 'When the ad set was created.';
COMMENT ON COLUMN public.meta_adset_state_daily.updated_time IS 'When Meta last recorded an edit of the ad set (any field).';
COMMENT ON COLUMN public.meta_adset_state_daily.snapshot_at IS 'When the row was written.';
COMMENT ON VIEW analytics.meta_change_log IS 'Meta''s own activity log of both ad accounts: every budget, bid, strategy, status, targeting, creation and creative change with who made it and when. The first place to look when a day''s spend, CPM or ROAS moved. Grain: one row per activity-log event. Source: public.meta_change_log (etl.meta_changes, Meta Marketing API activity log). Refresh: nightly, last 3 days re-read. Coverage: from the backfill start to yesterday: min(event_day) / max(event_day) over this view. Caveats: Most rows are noise for a performance story (first_delivery_event, run-status flips through Pending Review / Pending Process, billing charges, add_images / edit_images): filter object_level and event_type, for example update_ad_set_budget, update_ad_set_bid_strategy, update_campaign_budget, update_ad_set_run_status, update_ad_set_target_spec, create_ad_set. | object_level ''adset'' is what Meta''s raw object_type calls CAMPAIGN; ''campaign'' is CAMPAIGN_GROUP. Join object_id to meta_adset_daily.adset_id / meta_campaign_daily.campaign_id. | old_amount / new_amount are dollars (budget and bid events); old_roas_floor / new_roas_floor are ratios. extra_data is often incomplete for bids: cross-check analytics.meta_change_ledger. | event_day is the Pacific day of the event; Meta''s own account time zones differ (Main Pacific, BackUp Eastern), so an event near midnight can sit one day off from that account''s insight days. | A change is an event, not a cause: this view says what was changed, not what it did to performance.';
COMMENT ON COLUMN analytics.meta_change_log.event_time IS 'When Meta recorded the event.';
COMMENT ON COLUMN analytics.meta_change_log.event_day IS 'Pacific day of the event.';
COMMENT ON COLUMN analytics.meta_change_log.account IS 'Lonvera Main or Lonvera BackUp.';
COMMENT ON COLUMN analytics.meta_change_log.event_type IS 'Meta event type (update_ad_set_budget ...).';
COMMENT ON COLUMN analytics.meta_change_log.translated_event_type IS 'Meta''s readable name of the event type.';
COMMENT ON COLUMN analytics.meta_change_log.object_level IS 'ad | adset | campaign | account.';
COMMENT ON COLUMN analytics.meta_change_log.object_type IS 'Meta''s raw object type (ADGROUP = ad, CAMPAIGN = ad set, CAMPAIGN_GROUP = campaign).';
COMMENT ON COLUMN analytics.meta_change_log.object_id IS 'Id of the changed object.';
COMMENT ON COLUMN analytics.meta_change_log.object_name IS 'Name of the object at the time.';
COMMENT ON COLUMN analytics.meta_change_log.campaign_id IS 'Campaign of the object when known.';
COMMENT ON COLUMN analytics.meta_change_log.actor_name IS 'Who made the change (''Meta'' = system).';
COMMENT ON COLUMN analytics.meta_change_log.application_name IS 'App the change came through, when Meta says.';
COMMENT ON COLUMN analytics.meta_change_log.old_value IS 'Old value as text (status, strategy, name, targeting description); NULL for amounts.';
COMMENT ON COLUMN analytics.meta_change_log.new_value IS 'New value as text.';
COMMENT ON COLUMN analytics.meta_change_log.old_amount IS 'Old budget or bid, dollars.';
COMMENT ON COLUMN analytics.meta_change_log.new_amount IS 'New budget or bid, dollars (starting budget on create events; the amount on billing events).';
COMMENT ON COLUMN analytics.meta_change_log.old_roas_floor IS 'Old ROAS floor, ratio.';
COMMENT ON COLUMN analytics.meta_change_log.new_roas_floor IS 'New ROAS floor, ratio.';
COMMENT ON VIEW analytics.meta_adset_state_daily IS 'Daily snapshot of every live ad set''s settings (status, budget, bid, ROAS floor, optimization goal, attribution): the state of the account on each morning, the base of analytics.meta_change_ledger. Grain: one row per (day, adset_id). Source: public.meta_adset_state_daily (etl.meta_changes, Meta Marketing API adsets, read only). Refresh: nightly (~05:00 Pacific). Coverage: starts on the first snapshot day (min(day) over this view); it is not backfillable. Caveats: Taken in the early morning Pacific: a row for day D is the state at the start of D, so changes made on D-1 are already in it. | daily_budget is NULL under campaign budget optimization (the campaign owns the budget); bid_strategy is NULL when inherited. | Archived ad sets appear only for 3 days after their last update; an ad set missing from a day is archived, deleted or not pulled.';
COMMENT ON COLUMN analytics.meta_adset_state_daily.day IS 'Pacific snapshot day.';
COMMENT ON COLUMN analytics.meta_adset_state_daily.adset_id IS 'Meta ad set id.';
COMMENT ON COLUMN analytics.meta_adset_state_daily.adset_name IS 'Ad set name that day.';
COMMENT ON COLUMN analytics.meta_adset_state_daily.campaign_id IS 'Meta campaign id.';
COMMENT ON COLUMN analytics.meta_adset_state_daily.account IS 'Lonvera Main or Lonvera BackUp.';
COMMENT ON COLUMN analytics.meta_adset_state_daily.status IS 'ACTIVE | PAUSED | ARCHIVED | DELETED (configured).';
COMMENT ON COLUMN analytics.meta_adset_state_daily.effective_status IS 'ACTIVE only when ad set and campaign are on; else PAUSED, CAMPAIGN_PAUSED, ARCHIVED, IN_PROCESS, WITH_ISSUES.';
COMMENT ON COLUMN analytics.meta_adset_state_daily.daily_budget IS 'Daily budget, dollars (NULL under CBO).';
COMMENT ON COLUMN analytics.meta_adset_state_daily.lifetime_budget IS 'Lifetime budget, dollars.';
COMMENT ON COLUMN analytics.meta_adset_state_daily.bid_strategy IS 'Bid strategy (COST_CAP, LOWEST_COST_WITHOUT_CAP ...).';
COMMENT ON COLUMN analytics.meta_adset_state_daily.bid_amount IS 'Bid cap or cost-cap target, dollars.';
COMMENT ON COLUMN analytics.meta_adset_state_daily.roas_average_floor IS 'ROAS floor as a ratio.';
COMMENT ON COLUMN analytics.meta_adset_state_daily.optimization_goal IS 'Meta optimization goal.';
COMMENT ON COLUMN analytics.meta_adset_state_daily.attribution_spec IS 'Attribution windows (JSON).';
COMMENT ON COLUMN analytics.meta_adset_state_daily.created_time IS 'Ad set creation time.';
COMMENT ON COLUMN analytics.meta_adset_state_daily.updated_time IS 'Meta''s last-edit time of the ad set.';
COMMENT ON VIEW analytics.meta_change_ledger IS 'Ad set changes found by comparing each snapshot day with the previous one: new ad sets, paused / activated / archived, budget, bid, strategy, ROAS floor, optimization goal and attribution changes. Independent of the activity log, so it catches bid changes the log''s extra_data omits. Grain: one row per (day, adset_id, change_type). Source: analytics.meta_adset_state_daily (lag over consecutive snapshot days). Refresh: nightly with the snapshot. Coverage: starts on the SECOND snapshot day (min(day) over this view); a change is only visible once two consecutive snapshots exist. Caveats: A change happened between prev_day''s snapshot and day''s snapshot: the snapshot runs ~05:00 Pacific, so a change made on Pacific day D shows on day D+1 with prev_day D. A gap in prev_day means a missed snapshot, not a quiet period. | Only ad sets in the snapshot are compared. new_adset needs a creation time inside the gap, so old archived ad sets that are touched again do not show as new. Campaign budgets (CBO) are not in this view: use analytics.meta_change_log update_campaign_budget. | Several changes of the same ad set in one night collapse to the net difference; the sequence is in meta_change_log. | old_number / new_number are dollars for daily_budget, lifetime_budget and bid_amount, a ratio for roas_floor; NULL for text changes.';
COMMENT ON COLUMN analytics.meta_change_ledger.day IS 'Snapshot day on which the change is seen.';
COMMENT ON COLUMN analytics.meta_change_ledger.prev_day IS 'Previous snapshot day of this ad set (the change happened after it).';
COMMENT ON COLUMN analytics.meta_change_ledger.adset_id IS 'Meta ad set id.';
COMMENT ON COLUMN analytics.meta_change_ledger.adset_name IS 'Ad set name on day.';
COMMENT ON COLUMN analytics.meta_change_ledger.campaign_id IS 'Meta campaign id.';
COMMENT ON COLUMN analytics.meta_change_ledger.account IS 'Lonvera Main or Lonvera BackUp.';
COMMENT ON COLUMN analytics.meta_change_ledger.change_type IS 'new_adset | paused (ACTIVE -> PAUSED) | activated (PAUSED -> ACTIVE) | archived | effective_status | daily_budget | lifetime_budget | bid_amount | bid_strategy | roas_floor | optimization_goal | attribution_spec.';
COMMENT ON COLUMN analytics.meta_change_ledger.old_value IS 'Old value as text (NULL for new_adset).';
COMMENT ON COLUMN analytics.meta_change_ledger.new_value IS 'New value as text (for new_adset: its effective status).';
COMMENT ON COLUMN analytics.meta_change_ledger.old_number IS 'Old amount (dollars) or floor (ratio) for numeric changes.';
COMMENT ON COLUMN analytics.meta_change_ledger.new_number IS 'New amount or floor.';
